values ('00000000-0000-4000-a000-000000000003', '1.0', '{"identificacao.tipo_contrato":{"status":"inferido","value":{"categoria":"licenca_saas"},"citations":[],"confidence":"alta","origin":"ia","notes":"Inferido do objeto do contrato.","review":{"state":"pendente","by":null,"at":null,"comment":null}},"identificacao.papel_avenia":{"status":"encontrado","value":"contratante","citations":[{"quote":"(\"Avenia\", CONTRATANTE)","clause":"Preâmbulo","span":{"start":91,"end":114},"verified":true,"match":"exato"}],"confidence":"alta","origin":"ia","notes":null,"review":{"state":"confirmado","by":"Legal Demo","at":"2026-10-20T12:00:00.000Z","comment":null}},"identificacao.contraparte":{"status":"encontrado","value":{"nome":"NUVEM CONTÁBIL S.A. (fictícia)"},"citations":[{"quote":"NUVEM CONTÁBIL S.A. (fictícia)","clause":"Preâmbulo","span":{"start":117,"end":147},"verified":true,"match":"exato"}],"confidence":"alta","origin":"ia","notes":null,"review":{"state":"confirmado","by":"Legal Demo","at":"2026-10-20T12:00:00.000Z","comment":null}},"vigencia.prazo":{"status":"encontrado","value":{"tipo":"determinado","duracao":{"amount":12,"unit":"meses","day_count":"nao_especificado"}},"citations":[{"quote":"vigorará por 12 (doze) meses","clause":"cl. 5.1","span":{"start":362,"end":390},"verified":true,"match":"exato"}],"confidence":"alta","origin":"ia","notes":null,"review":{"state":"pendente","by":null,"at":null,"comment":null}},"vigencia.renovacao":{"status":"encontrado","value":{"tipo":"automatica","aviso_nao_renovacao":{"amount":30,"unit":"dias","day_count":"nao_especificado"},"limite_renovacoes":null},"citations":[{"quote":"será renovado automaticamente por iguais períodos","clause":"cl. 5.1","span":{"start":393,"end":442},"verified":true,"match":"exato"}],"confidence":"alta","origin":"ia","notes":null,"review":{"state":"pendente","by":null,"at":null,"comment":null}},"rescisao.imotivada":{"status":"nao_encontrado","value":null,"citations":[],"confidence":null,"origin":"ia","notes":null,"review":{"state":"pendente","by":null,"at":null,"comment":null}},"alteracao_parte.cessao":{"status":"encontrado","value":{"regime":"vedada","aplica_a":"avenia","excecoes":[]},"citations":[{"quote":"A Avenia não poderá ceder este Contrato","clause":"cl. 7.1","span":{"start":545,"end":584},"verified":true,"match":"exato"}],"confidence":"alta","origin":"ia","notes":null,"review":{"state":"pendente","by":null,"at":null,"comment":null}},"dados_pessoais.compartilhamento":{"status":"encontrado","value":true,"citations":[{"quote":"As Partes tratarão dados pessoais","clause":"cl. 9.1","span":{"start":693,"end":726},"verified":true,"match":"exato"}],"confidence":"alta","origin":"ia","notes":null,"review":{"state":"pendente","by":null,"at":null,"comment":null}},"dados_pessoais.dpa":{"status":"encontrado","value":"por_referencia","citations":[{"quote":"Política de Privacidade disponível no site da CONTRATADA","clause":"cl. 9.1","span":{"start":772,"end":828},"verified":true,"match":"exato"}],"confidence":"alta","origin":"ia","notes":null,"review":{"state":"pendente","by":null,"at":null,"comment":null}},"responsabilidade.limitacao":{"status":"encontrado","value":{"existe":true,"protege":"ambas","tipo":"meses_remuneracao","meses":12},"citations":[{"quote":"limitada ao valor pago nos 12 (doze) meses anteriores ao evento","clause":"cl. 11.1","span":{"start":904,"end":967},"verified":true,"match":"exato"}],"confidence":"alta","origin":"ia","notes":null,"review":{"state":"pendente","by":null,"at":null,"comment":null}},"foro.lei_aplicavel":{"status":"encontrado","value":{"jurisdicao":"US-NY"},"citations":[{"quote":"regido pelas leis do Estado de Nova York","clause":"cl. 20.1","span":{"start":1055,"end":1095},"verified":true,"match":"exato"}],"confidence":"alta","origin":"ia","notes":null,"review":{"state":"pendente","by":null,"at":null,"comment":null}}}'::jsonb, '00000000-0000-4000-d100-000000000001', '00000000-0000-4000-e200-000000000001', 'previa-stub', 'ficha-revisao-v1', '1.0', '[{"rule_id":"REN-01","rules_version":"1.0","titulo":"Renovação automática com aviso prévio curto","severidade":"alta","justificativa":"Com aviso menor que 60 dias, a decisão de não renovar precisa sair antes do ciclo orçamentário e de aprovação interna. É o caminho mais comum para renovar sem querer.","acao_sugerida":"Negociar aviso de 60 a 90 dias ou renovação mediante aditivo.","campos":["vigencia.renovacao"],"depende_de_campo_nao_validado":true},{"rule_id":"ALT-03","rules_version":"1.0","titulo":"Avenia não pode ceder nem para empresas do grupo","severidade":"media","justificativa":"O grupo tem várias entidades (IP, SPSAV, LLC, holdings). Reorganizar onde o contrato fica passa a depender da contraparte.","acao_sugerida":"Exceção para cessão a afiliadas e sucessoras por reorganização societária.","campos":["alteracao_parte.cessao"],"depende_de_campo_nao_validado":true},{"rule_id":"LGP-02","rules_version":"1.0","titulo":"Termos de dados só por referência, fora do documento","severidade":"media","justificativa":"As regras reais de tratamento de dados estão num documento que não foi analisado e pode mudar.","acao_sugerida":"Anexar a versão vigente do documento ao contrato e analisá-la.","campos":["dados_pessoais.dpa"],"depende_de_campo_nao_validado":true},{"rule_id":"FOR-01","rules_version":"1.0","titulo":"Lei estrangeira ou foro fora do Brasil","severidade":"media","justificativa":"Disputa cara e lenta; contrato precisa de revisão por advogado da jurisdição.","acao_sugerida":"Avaliar arbitragem internacional ou lei brasileira para a entidade brasileira.","campos":["foro.lei_aplicavel"],"depende_de_campo_nao_validado":true}]'::jsonb, 'atencao', now() - interval '3 hours', now() - interval '3 hours')
on conflict (project_id) do nothing;
